head.script:
scwin.onpageload = function() {
    scwin.dl_Create("dataList1");
    var treeData = [{
        label: "label1",
        value: "value1",
        depth: "1",
        check: "T"
    }, {
        label: "label2",
        value: "value2",
        depth: "2",
        check: "T"
    }, {
        label: "label3",
        value: "value3",
        depth: "3",
        check: "F"
    }, {
        label: "label4",
        value: "value4",
        depth: "2",
        check: "F"
    }, {
        label: "label5",
        value: "value5",
        depth: "3",
        check: "T"
    }, {
        label: "label6",
        value: "value6",
        depth: "4",
        check: "F"
    }];
    dataList1.setJSON(treeData);
    var id = "trv1";
    var tagName = "treeview";
    var options = {
        showTreeDepth: "2",
        showCheckbox: "true",
        hierarchy: "true",
        trueValue: "T",
        falseValue: "F"
    };
    var parentEle = group1;
    var itemSet = dataList1;
    //		debugger;
    $p.dynamicCreate(id, tagName, options, parentEle, itemSet);
};
scwin.onpageunload = function() {};
scwin.dl_Create = function(dlId) {
    var option = {
        "id": dlId,
        "type": "dataList",
        "option": {
            "baseNode": "list",
            "repeatNode": "map"
        },
        "columnInfo": [{
            "id": "label",
            "name": "name1",
            "dataType": "text"
        }, {
            "id": "value",
            "name": "name2",
            "dataType": "text"
        }, {
            "id": "depth",
            "name": "name3",
            "dataType": "text"
        }, {
            "id": "check",
            "name": "name4",
            "dataType": "text"
        }]
    };
    $p.data.create(option);
};
scwin.getErrorLog = function() {
    var temp = WebSquare.logger.getErrorLog();
    return temp;
}
scwin.unitTest = function() {
    //Unit tets
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.getErrorLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
